select case when suppliers.rating >= 4.2 then 'high' when suppliers.rating >= 2.1 then 'mid' else 'low' end as rating_bucket, min(products.launch_date) as min_launch_date, concat_ws(', ', sort_array(collect_set(products.category))) as category_values from products join suppliers on products.supplier_id = suppliers.id where products.brand in ('Initech', 'Stark') group by case when suppliers.rating >= 4.2 then 'high' when suppliers.rating >= 2.1 then 'mid' else 'low' end order by rating_bucket desc
